pragma solidity 0.8.35;

abstract contract StorageStructs {
    struct TokenSources {
        // ---------- storage slot 0 ----------
        address source1; // 160 -- primary source 1 address
        int8 multiplier1; // 8  -- decimals multiplier: positive = multiply, negative = divide, to get to 1e27
        uint8 sourceType1; // 8 -- source type (see SOURCE_* constants)
        uint8 sourceType2; // 8 -- stored in slot 0 to avoid loading slot 1 just to check existence
        uint8 sourceType3; // 8 -- stored in slot 0 to avoid loading slot 2 just to check existence
        uint16 capOperand1; // 16 -- cap bound for leg 1 in 2-decimal precision (100 = 1.00). 0 = no cap.
        // -------------------------------------
        // Metadata (only meaningful on `_tokenSources.primarySrc`; zero on alt/additional buckets).
        uint8 pauseState; // 8 -- bit 0 = operate paused, bit 1 = liquidate paused
        uint8 tokenType; // 8  -- 0 = not listed, 1 = PEG, 2 = STABLE, 3 = VOLATILE
        uint8 decimals; // 8   -- IERC20.decimals() or 18 for native token
        /// @dev Stored and read only on `_tokenSources`, never on `_additionalTokenSources`.
        ///      Some bits describe whether corresponding configs exist in `_additionalTokenSources`.
        ///      bit 0 (FLAG_HAS_ALT_SOURCE): alt sources exist in this mapping (storage slots 3-5 / `altSrc`)
        ///      bit 1 (FLAG_HAS_ADDITIONAL_SOURCES): _additionalTokenSources has primary sources
        ///      bit 2 (FLAG_HAS_ADDITIONAL_ALT_SOURCES): _additionalTokenSources has alt sources
        ///      bit 3 (FLAG_GOVERNANCE_APPROVED): token-level sources approved by governance for downstream policy (e.g. borrow limits)
        uint8 flagsBitmap; // 8
        // -------------------------------------
        uint16 __placeholder1; // 16 -- future slot 0 expansion
        // ---------- storage slot 1 ----------
        int8 multiplier2;
        address source2;
        uint16 capOperand2; // 16 -- cap bound for leg 2
        uint72 __placeholder2;
        // ---------- storage slot 2 ----------
        int8 multiplier3;
        address source3;
        uint16 capOperand3; // 16 -- cap bound for leg 3
        uint72 __placeholder3;
    }

    /// @dev Token-level source configuration using reusable three-source storage buckets.
    ///      `_tokenSources.primarySrc` packs metadata into storage slot 0 of the mapping value.
    ///      `_additionalTokenSources` and `altSrc` reuse the same shape but ignore metadata bytes.
    ///      Full `_tokenSources[token]` layout: slots 0-2 = `primarySrc`, slots 3-5 = `altSrc`.
    struct TokenSourceConfig {
        TokenSources primarySrc;
        TokenSources altSrc;
    }

    /// @dev Per-(token, eMode, isOperate, isCollateral) key configuration. Fits in 1 storage slot.
    ///      Intentionally slim: only stores a priceMode reference (which token-level source mapping
    ///      to read) plus key-specific parameters. Source feeds are configured per-token once and
    ///      shared by all keys for that token+mode — avoiding redundant feed storage and verification.
    struct OracleKeyConfig {
        uint8 priceMode; // PRICE_MODE_MARKET or PRICE_MODE_PEG
        uint8 sourceCapMode; // SOURCE_CAP_NONE / SOURCE_CAP_MIN / SOURCE_CAP_MAX
        uint8 overallCapMode; // OVERALL_CAP_NONE / MIN_CROSS_PATH / MAX_CROSS_PATH / MIN_OPERAND / MAX_OPERAND
        uint16 overallCapOperand; // 2-decimal precision bound for *_OPERAND modes (100 = 1.00). 0 for cross-path/none.
        uint24 maxDeviationBPS; // max deviation in basis points (100 = 1%). 0 = disabled.
        uint8 flagsBitmap; // bit 0: fallback enabled (KEY_FLAG_FALLBACK)
    }

    struct ConfigMap {
        uint240 eMode;
        bool isOperate;
        bool isCollateral;
    }
}

abstract contract MemoryStructs {
    struct SourceConfig {
        uint8 sourceType;
        address source;
        uint16 capOperand; // cap bound in 2-decimal precision (100 = 1.00). 0 = no cap for this leg.
    }

    struct OracleKey {
        address token;
        uint256 eMode;
        uint8 isOperate; // 0 = liquidate, 1 = operate
        uint8 isCollateral; // 0 = debt, 1 = collateral
    }
}

abstract contract ViewStructs {
    struct TokenMetadata {
        uint8 pauseState;
        uint8 tokenType;
        uint8 decimals;
        uint8 flagsBitmap;
    }

    struct SourcesWithRates {
        MemoryStructs.SourceConfig source1;
        MemoryStructs.SourceConfig source2;
        MemoryStructs.SourceConfig source3;
        uint256 rate1;
        uint256 rate2;
        uint256 rate3;
        uint256 price;
    }

    struct ConfiguredTokenOracle {
        address token;
        string symbol;
        uint256 eMode;
        bool isOperate;
        bool isCollateral;
        uint8 priceMode;
        SourcesWithRates primary;
        SourcesWithRates alt;
        uint8 sourceCapMode;
        uint8 overallCapMode;
        uint16 overallCapOperand;
        uint24 maxDeviationBPS;
        bool isFallback;
        bool governanceApproved;
    }
}

abstract contract Structs is ViewStructs, StorageStructs, MemoryStructs {}
","keccak256":"0x3fe7b28375fce284661d885b03a63a1b83e610a7564e9a1201b54da818ebd7e4","license":"BUSL-1.1"},"contracts/oracleV2/vaultOracle/base.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.35;

import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import { IFluidOracle } from "../interfaces/iFluidOracle.sol";
import { IUSDOracle } from "../interfaces/iUSDOracle.sol";
import { DexShareResolver } from "../common/dexShareResolver.sol";
import { TokenSymbolResolver } from "../common/tokenSymbolResolver.sol";
import { Error as VaultError } from "./error.sol";
import { ErrorTypes } from "./errorTypes.sol";

/// @title VaultOracleBase
/// @notice Abstract base for vault oracles. Inherits DexShareResolver for share pricing,
///         TokenSymbolResolver for `_tokenSymbol`, and adds normal token resolution + exchange rate computation.
///
///         USD Oracle reads use immutable supply/borrow eModes (per deployment).
///         Exchange rate = debt-per-collateral in 1e27 precision adjusted for token decimals.
abstract contract VaultOracleBase is DexShareResolver, TokenSymbolResolver, VaultError, IFluidOracle {
    /// @notice eMode passed to `FluidUsdOracle` for collateral-side price reads from this vault oracle.
    uint256 internal immutable SUPPLY_E_MODE;
    /// @notice eMode passed to `FluidUsdOracle` for debt-side price reads from this vault oracle.
    uint256 internal immutable BORROW_E_MODE;

    address internal constant NATIVE_TOKEN_ADDRESS = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;
    /// @dev Fluid protocol rate / USD price fixed-point scale (1e27).
    uint256 internal constant FLUID_RATE_DECIMALS = 27;
    /// @dev Vault-oracle DEX share pricing: operate path uses 0.5% reserve adjustment (ppm on `PEG_BUFFER_SCALE`).
    uint256 internal constant PEG_BUFFER_PPM_OPERATE = 5000;
    /// @dev Vault-oracle DEX share pricing: liquidate path uses 0.1% reserve adjustment.
    uint256 internal constant PEG_BUFFER_PPM_LIQUIDATE = 1000;

    constructor(uint256 supplyEMode_, uint256 borrowEMode_) {
        SUPPLY_E_MODE = supplyEMode_;
        BORROW_E_MODE = borrowEMode_;
    }

    function infoName() public view returns (string memory) {
        return string.concat(_debtName(), " / 1 ", _collateralName());
    }

    /// @notice Returns canonical vault-oracle config fields across T1-T4.
    /// @dev Non-applicable fields are returned as address(0) depending on vault type.
    function getOracleConfig()
        external
        view
        returns (
            address usdOracle_,
            address supplyToken0_,
            address supplyToken1_,
            address borrowToken0_,
            address borrowToken1_,
            address supplyDexPool_,
            address borrowDexPool_,
            uint256 supplyEMode_,
            uint256 borrowEMode_
        )
    {
        (
            usdOracle_,
            supplyToken0_,
            supplyToken1_,
            borrowToken0_,
            borrowToken1_,
            supplyDexPool_,
            borrowDexPool_
        ) = _oracleConfigAddresses();
        supplyEMode_ = SUPPLY_E_MODE;
        borrowEMode_ = BORROW_E_MODE;
    }

    function targetDecimals() public view returns (uint8 targetDecimals_) {
        targetDecimals_ = uint8(FLUID_RATE_DECIMALS + _debtDecimals() - _collateralDecimals());
    }

    /// @notice Get the exchange rate for operate mode.
    function getExchangeRateOperate() external view returns (uint256 exchangeRate_) {
        return _getExchangeRate(true, false);
    }

    /// @notice Get the exchange rate for liquidate mode.
    function getExchangeRateLiquidate() external view returns (uint256 exchangeRate_) {
        return _getExchangeRate(false, false);
    }

    /// @dev Deprecated. Same as operate.
    function getExchangeRate() external view returns (uint256 exchangeRate_) {
        return _getExchangeRate(true, false);
    }

    /// @inheritdoc IFluidOracle
    function getExchangeRateOperateRaw() external view returns (uint256 exchangeRate_) {
        return _getExchangeRate(true, true);
    }

    /// @inheritdoc IFluidOracle
    function getExchangeRateLiquidateRaw() external view returns (uint256 exchangeRate_) {
        return _getExchangeRate(false, true);
    }

    /// @inheritdoc IFluidOracle
    function getExchangeRateRaw() external view returns (uint256 exchangeRate_) {
        return _getExchangeRate(true, true);
    }

    /// @notice Resolves the USD price and decimals of a normal (non-share) collateral token.
    function _resolveNormalCol(
        address usdOracle_,
        address token_,
        bool isOperate_,
        bool isRaw_
    ) internal view returns (uint256 priceUsd_, uint256 decimals_) {
        uint8 dec_;
        if (isRaw_) {
            (priceUsd_, dec_, ) = IUSDOracle(usdOracle_).getPriceDetailedViewRaw(
                token_,
                SUPPLY_E_MODE,
                isOperate_,
                true
            );
        } else {
            (priceUsd_, dec_, ) = IUSDOracle(usdOracle_).getPriceDetailedView(token_, SUPPLY_E_MODE, isOperate_, true);
        }
        decimals_ = uint256(dec_);
        if (priceUsd_ == 0) {
            revert FluidVaultOracleError(ErrorTypes.VaultOracle__PriceZero);
        }
    }

    /// @notice Resolves the USD price and decimals of a normal (non-share) debt token.
    function _resolveNormalDebt(
        address usdOracle_,
        address token_,
        bool isOperate_,
        bool isRaw_
    ) internal view returns (uint256 priceUsd_, uint256 decimals_) {
        uint8 dec_;
        if (isRaw_) {
            (priceUsd_, dec_, ) = IUSDOracle(usdOracle_).getPriceDetailedViewRaw(
                token_,
                BORROW_E_MODE,
                isOperate_,
                false
            );
        } else {
            (priceUsd_, dec_, ) = IUSDOracle(usdOracle_).getPriceDetailedView(token_, BORROW_E_MODE, isOperate_, false);
        }
        decimals_ = uint256(dec_);
        if (priceUsd_ == 0) {
            revert FluidVaultOracleError(ErrorTypes.VaultOracle__PriceZero);
        }
    }

    /// @dev Peg buffer for T2–T4 DEX share legs: `isOperate_ == true` → 0.5% ppm; liquidate → 0.1% ppm.
    function _dexSharePegBufferPpm(bool isOperate_) internal pure returns (uint256 pegBufferPpm_) {
        pegBufferPpm_ = isOperate_ ? PEG_BUFFER_PPM_OPERATE : PEG_BUFFER_PPM_LIQUIDATE;
    }

    /// @dev Computes the exchange rate between collateral and debt.
    ///      rate = colPriceUsd * 10^(27 + debtDecimals - colDecimals) / debtPriceUsd
    ///
    ///      Example: ETH (18 dec) / USDC (6 dec) at $2000/$1:
    ///        2000e27 * 10^(27+6-18) / 1e27 = 2000e27 * 1e15 / 1e27 = 2000 * 1e15 = 2e18
    ///        targetDecimals = 15, so 2e18 represents 2000 USDC per ETH.
    function _computeExchangeRate(
        uint256 colPriceUsd_,
        uint256 colDecimals_,
        uint256 debtPriceUsd_,
        uint256 debtDecimals_
    ) internal pure returns (uint256 exchangeRate_) {
        exchangeRate_ = (colPriceUsd_ * (10 ** (FLUID_RATE_DECIMALS + debtDecimals_ - colDecimals_))) / debtPriceUsd_;
    }

    function _tokenDecimals(address token_) internal view returns (uint256 decimals_) {
        if (token_ == NATIVE_TOKEN_ADDRESS) {
            return DEX_SHARE_DECIMALS;
        }
        decimals_ = uint256(IERC20Metadata(token_).decimals());
    }

    function _dexPairName(address token0_, address token1_) internal view returns (string memory) {
        return string.concat(_tokenSymbol(token0_), "-", _tokenSymbol(token1_));
    }

    function _oracleConfigAddresses()
        internal
        view
        virtual
        returns (
            address usdOracle_,
            address supplyToken0_,
            address supplyToken1_,
            address borrowToken0_,
            address borrowToken1_,
            address supplyDexPool_,
            address borrowDexPool_
        );

    /// @dev Each vault oracle implements this to wire its specific collateral/debt resolution.
    /// @param isRaw_ When true, use raw oracle reads (`getPriceDetailedViewRaw`, etc.) that may bypass guarded checks (e.g. L2 sequencer uptime today).
    function _getExchangeRate(bool isOperate_, bool isRaw_) internal view virtual returns (uint256 exchangeRate_);

    function _collateralName() internal view virtual returns (string memory);

    function _debtName() internal view virtual returns (string memory);

    function _collateralDecimals() internal view virtual returns (uint256);

    function _debtDecimals() internal view virtual returns (uint256);
}
